-- Keep the public announcement and editor preview on the same explicit allowlist.
-- Confidential salaries remain redacted; no private fields are exported.
create or replace function public.public_jobs_v1(requested_slug text) returns jsonb language sql stable security definer set search_path=pg_catalog as $$
 select coalesce(jsonb_agg(jsonb_build_object('tools',j.document->'tools','languages',j.document->'languages','reportsTo',j.document->'reportsTo','teamSize',j.document->'teamSize','methodology',j.document->'methodology','performanceReviews',j.document->'performanceReviews','promotionPossible',j.document->'promotionPossible','technicalTest',j.document->'technicalTest')||jsonb_build_object('stages',j.document->'stages','experience',j.document->'experience','weeklyHours',j.document->'weeklyHours','schedule',j.document->'schedule','challenges',j.document->'challenges','salaryConfidential',j.document->'salaryConfidential','pcd',j.document->'pcd','journey',j.document->'journey','description',j.document->'description','attributions',j.document->'attributions','additionalBenefits',j.document->'additionalBenefits','careerPlan',j.document->'careerPlan','education',j.document->'education','certifications',j.document->'certifications','softSkills',j.document->'softSkills','differentiators',j.document->'differentiators','interviewTypes',j.document->'interviewTypes','applicationDeadline',j.document->'applicationDeadline','responseSla',j.document->'responseSla','contactEmail',j.document->'contactEmail','contactPhone',j.document->'contactPhone','contactWhatsapp',j.document->'contactWhatsapp','salaryRange',case when j.document->>'salaryConfidential'='true' then '' else coalesce(j.document->>'salaryRange','') end,'branches',coalesce((select jsonb_agg(jsonb_build_object('id',f.id,'name',f.document->>'name','city',f.document->>'city','state',f.document->>'state','street',f.document->>'street','number',f.document->>'number','district',f.document->>'district','description',f.document->>'description') order by f.document->>'name') from app_private.company_branches f where f.company_id=j.company_id and f.document->>'status'='Ativo' and f.document->'jobIds' ? j.id::text),'[]'::jsonb),'id',j.id,'title',j.document->'title','area',j.document->'area','level',j.document->'level','contractType',j.document->'contractType','modality',j.document->'modality','city',j.document->'city','state',j.document->'state','summary',j.document->'summary','responsibilities',j.document->'responsibilities','requirements',j.document->'requirements','benefits',j.document->'benefits','teamDescription',j.document->'teamDescription','salaryMin',case when j.document->>'salaryConfidential'='true' then '' else j.document->>'salaryMin' end,'salaryMax',case when j.document->>'salaryConfidential'='true' then '' else j.document->>'salaryMax' end,'currency',j.document->'currency') order by j.updated_at desc),'[]')
 from app_private.company_jobs j join public.company_portals p on p.company_id=j.company_id join public.companies c on c.id=j.company_id join public.company_branding b on b.company_id=j.company_id
 where p.slug=requested_slug and p.is_public and c.operational_status='active' and b.published<>'{}'::jsonb and j.status='Publicada' and j.deleted_at is null;
$$;


notify pgrst,'reload schema';
